"implementation": "def solve(case):
    payload = case["payload"]
    nodes = payload["nodes"]
    required_symbols = payload["required_symbols"]
    if not isinstance(nodes, list) or len(nodes) == 0:
        raise ValueError("nodes must be non-empty list")
    node_map = {}
    children_map = {}
    root_id = None
    for node in nodes:
        nid = node["id"]
        parent = node.get("parent")
        symbol = node.get("symbol")
        depth = node.get("depth")
        removable = node.get("removable")
        utility = node.get("utility")
        if nid is None or (parent is None and depth != 0):
            raise ValueError("root must have depth 0 and parent null")
        node_map[nid] = node
        if parent is None:
            if root_id is not None:
                raise ValueError("multiple roots")
            root_id = nid
        else:
            children_map.setdefault(parent, []).append(nid)
    for node in nodes:
        parent = node["parent"]
        if parent is not None and parent not in node_map:
            raise ValueError(f"parent {parent} not found")
    if root_id is None:
        raise ValueError("no root")
    root = node_map[root_id]
    if root["depth"] != 0:
        raise ValueError("root depth must be 0")
    all_symbols = set(node["symbol"] for node in nodes)
    for sym in required_symbols:
        if sym not in all_symbols:
            raise ValueError(f"required symbol {sym} not present")
    symbol_counts = {sym: 0 for sym in required_symbols}
    for node in nodes:
        if node["symbol"] in symbol_counts:
            symbol_counts[node["symbol"]] += 1
    candidate_nodes = []
    for node in nodes:
        if node["id"] == root_id:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required_symbols:
            continue
        candidate_nodes.append(node)
    candidate_nodes.sort(key=lambda n: (-n["depth"], n["id"]))
    removed = set()
    removed_order = []
    for node in candidate_nodes:
        nid = node["id"]
        if nid in removed:
            continue
        has_retained_child = False
        for child_id in children_map.get(nid, []):
            if child_id not in removed:
                has_retained_child = True
                break
        if has_retained_child:
            continue
        removed.add(nid)
        removed_order.append(nid)
    all_ids = set(node["id"] for node in nodes)
    retained_ids = sorted(all_ids - removed)
    return {"retained_ids": retained_ids, "removed_order": removed_order}"
}
